local Singleton = import('Frame.Singleton')
---@class RegressionActivityMgr
---@field GetInstance fun(self:RegressionActivityMgr):RegressionActivityMgr
local RegressionActivityMgr = Class('RegressionActivityMgr', Singleton)
local RegressionActivityConstants = import("Game.Activity.RegressionActivity.RegressionActivityConstants")
local RegressionDojo = import("Game.Dojo.RegressionDojo")

function RegressionActivityMgr:__init()
    ---@type RegressionDojo
    self.regressionDojo = nil
end

function RegressionActivityMgr:RequestHomeDojo(callBack)
    GameUtils.Request(Interfaces.NewRegressHome, nil, function(request, response)
        if checkNumber(response.errCode) == 0 then
            if isNull(self.regressionDojo) then
                self.regressionDojo = RegressionDojo.New()
            end
            self.regressionDojo:Fill(response.data)
            if callBack then
                callBack()
            end
        end
    end)
end

---GetHomeDojo
---@return RegressionDojo
function RegressionActivityMgr:GetHomeDojo()
    return self.regressionDojo
end

---GetTasksByGroup
---得到每天的任务组
---@param day number
function RegressionActivityMgr:GetTasksByGroup(day)
    day = checkNumber(day)
    local t = {}
    for i, v in pairs(self.regressionDojo.taskInfo.task) do
        if checkNumber(v.openDay) == day then
            table.insert(t, v)
        end
    end
    return t
end

---GetTaskGroups
---@return table
function RegressionActivityMgr:GetTaskGroups()
    local t = {}
    for i, v in pairs(self.regressionDojo.taskInfo.task) do
        if not table.haskey(t, checkNumber(v.openDay)) then
            table.insert(t, checkNumber(v.openDay))
        end
    end
    return t
end

---GetTaskGroups
---@return table
function RegressionActivityMgr:GetTaskMaxUnlockGroupId()
    return checkInt(self.regressionDojo.taskInfo.todayNum)
end

---HasTaskGroupDawned
---@return boolean
function RegressionActivityMgr:HasTaskGroupDawned(day)
    local hasDrawn = true
    for i, v in pairs(self.regressionDojo.taskInfo.task) do
        if checkNumber(v.openDay) == checkNumber(day) then
            if checkNumber(v.status) ~= 2 then
                ---存在未领取的节点
                hasDrawn = false
            end
        end
    end
    return hasDrawn
end

---HasTaskGroupDawned
---@return boolean
function RegressionActivityMgr:GetTaskGroupProgress(day)
    local pro = 0
    local max = 0
    for i, v in pairs(self.regressionDojo.taskInfo.task) do
        if checkNumber(v.openDay) == checkNumber(day) then
            max = max + 1
            if checkNumber(v.status) == 2 then
                pro = pro + 1
            end
        end
    end
    return pro, max
end

function RegressionActivityMgr:HasRedPointGroupByDay(day)
    local hasRed = false
    for i, v in pairs(self.regressionDojo.taskInfo.task) do
        if checkNumber(v.openDay) == checkNumber(day) then
            if checkNumber(v.status) == 1 then
                hasRed = true
            end
        end
    end
    return hasRed
end

---@return boolean
function RegressionActivityMgr:UpdateTaskStatus(day, taskId, status)
    for i, v in pairs(self.regressionDojo.taskInfo.task) do
        if checkNumber(v.openDay) == checkNumber(day) and checkNumber(v.taskId) == checkNumber(taskId) then
            v.status = checkNumber(status)
            self.regressionDojo.taskInfo.point = checkNumber(self.regressionDojo.taskInfo.point) + checkNumber(v.point)
        end
    end
    self:FreshBoxStatus()
end

---GetTaskInfo
---return table
function RegressionActivityMgr:GetTaskInfo()
    return self.regressionDojo.taskInfo
end

function RegressionActivityMgr:FreshBoxStatus()
    local taskPoint = checkInt(self.regressionDojo.taskInfo.point)
    for i, v in pairs(self.regressionDojo.taskInfo.taskBox) do
        if checkInt(v.unlockPoint) <= taskPoint and checkInt(v.status) == Constants.GetStatus.Not then
            --如果数据值达到了，并且当前未领取的情况状态更新
            v.status = Constants.GetStatus.Can
        end
    end
end

function RegressionActivityMgr:UpdateTaskBoxStatus(boxId, status)
    for i, v in pairs(self.regressionDojo.taskInfo.taskBox) do
        if checkNumber(v.id) == checkNumber(boxId) then
            v.status = checkNumber(status)
            --self.regressionDojo.taskInfo.point = checkNumber(self.regressionDojo.taskInfo.point) + checkNumber(v.unlockPoint)
        end
    end
    --self:FreshBoxStatus()
end
----redPoint----------------------
function RegressionActivityMgr:CheckBattleRedPoint()
    local data = self.regressionDojo:GetJackPotInfo()
    local isHaveItem = GoodsUtils.GetThingNo(data.costId) > 0
    if isHaveItem then
        return true
    end

    local isHaveCircleReward = false
    local totalCircle = data.nowRound - 1
    local curReceiveId = data.receiveRoundId
    for i, v in pairs(data.roundRewardsInfo) do
        if tonumber(v.id) > tonumber(curReceiveId) and totalCircle >= tonumber(v.rounds) then
            isHaveCircleReward = true
        end
    end
    return isHaveCircleReward
end

function RegressionActivityMgr:CheckDailySignRedPoint()
    local data = self.regressionDojo:GetDailySignInfo()
    for i, v in pairs(data.loginList) do
        if v.status == Constants.GetStatus.Can then
            return true
        end
    end
    return false
end

function RegressionActivityMgr:CheckTaskRedPoint()
    ---判断是否存在任务红点
    local hasRed = false
    local day = self:GetTaskMaxUnlockGroupId()
    for i, v in pairs(self.regressionDojo.taskInfo.task) do
        if checkNumber(v.status) == 1 and v.openDay <= day then
            hasRed = true
            break
        end
    end
    for i, v in pairs(self.regressionDojo.taskInfo.taskBox) do
        if checkNumber(v.status) == Constants.GetStatus.Can then
            hasRed = true
            break
        end
    end
    return hasRed
end

function RegressionActivityMgr:CheckGiftRedPoint()
    local data = self.regressionDojo:GetGiftInfo()
    for j, v in pairs(data.products) do
        local isFree = self:ProductIsFree(v)
        if isFree and v.currentStock > 0 then
            return true
        end
    end
    return false
end

function RegressionActivityMgr:ProductIsFree(product)
    if product.prices and table.count(product.prices) > 0 then
        for i = 1, #product.prices do
            if product.prices[i].current ~= 0 then
                return false
            end
        end
        return true
    end

    return checkInt(product.isFree) == 1
end

---更新主界面红点
---UpdateRegressHomeRedPoint
function RegressionActivityMgr:UpdateRegressHomeRedPoint()
    local battleRedPoint = self:CheckBattleRedPoint()
    if battleRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainRegressionNew, 1)
        return
    end
    local dailySignRedPoint = self:CheckDailySignRedPoint()
    if dailySignRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainRegressionNew, 1)
        return
    end
    local taskRedPoint = self:CheckTaskRedPoint()
    if taskRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainRegressionNew, 1)
        return
    end
    local giftRedPoint = self:CheckGiftRedPoint()
    if giftRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainRegressionNew, 1)
        return
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.MainRegressionNew, 0)
end

